"""Sourced local price references and practical, behavior-based buying guidance."""
import html
import shutil
from editorial import write_editorial_page

FTC_HOME = 'https://consumer.ftc.gov/articles/how-avoid-home-improvement-scam'
FTC_AUTO = 'https://consumer.ftc.gov/articles/0211-auto-repair-basics'
NAR = 'https://www.nar.realtor/the-facts/consumer-guide-to-written-buyer-agreements'
MAINTENANCE = 'https://www.mtownhvac.com/services/contracts/'
DUCTLESS = 'https://www.mtownhvac.com/ductless-estimator/'
WRAPS = 'https://www.soundwraps.com/services.html'

# Editorial questions, not allegations about any listed or unlisted business.
INDUSTRIES = [
 ('hvac', 'Heating, cooling & ductless', 'A countdown isn’t a diagnosis.', 'A same-day sales deadline does not explain what failed. Ask for the findings, the repair option when applicable, and why replacement is recommended. If it is safe to wait, consider another assessment before a major purchase.', 'What failed, what are my options, and what is included in the installed price?', '/businesses/middletown-hvac/', FTC_HOME),
 ('water-heaters', 'Water heaters & boilers', 'The tank is only part of the total.', 'Ask whether removal, venting, controls, connections and permit responsibilities are included. A lower equipment number is hard to compare with a complete installed proposal.', 'What work beyond the equipment is included, and what could change the price?', '/businesses/middletown-hvac/', FTC_HOME),
 ('plumbing', 'Plumbing & drains', 'A scary description needs a clear explanation.', 'For a proposed major repair, ask what the inspection found and whether any available images or report can be shared. Agree on the diagnostic charge, repair scope and approval process before additional work.', 'Can you show me the finding and separate the investigation from the proposed repair?', '/businesses/liberator-service-company/', FTC_HOME),
 ('electrical', 'Electrical', '“Unsafe” deserves specifics.', 'Take a reported hazard seriously. Ask the electrician to explain the finding, immediate precautions and proposed correction in writing. A safety conversation should help you understand the work; do not open panels or investigate live wiring yourself.', 'What needs immediate attention, and what is an optional improvement?', '/businesses/ryan-dugan-electric/', FTC_HOME),
 ('painting', 'Painting & drywall', 'The bargain can be in the missing prep.', 'Compare preparation, repairs, surfaces, paint products, coats and cleanup. A room price without those details leaves plenty of room for a different bill.', 'Which preparation and repairs are included, and how are added surfaces priced?', '/#find', FTC_HOME),
 ('carpentry', 'Carpentry & home repairs', 'Small job. Clear boundaries.', 'Agree on materials, disposal, access and whether the quote is fixed or based on time. Ask how concealed damage and extra work will be approved.', 'What is the stopping point if you uncover more work than we expected?', '/businesses/cooke-carpentry-construction/', FTC_HOME),
 ('remodeling', 'Remodeling, decks & additions', 'The dream needs a change-order plan.', 'Before a deposit, compare the written scope, allowances, milestones and exclusions. Ask who handles permits and who approves a price change. Keep payment terms tied to the agreed contract and applicable local requirements.', 'How do we approve a change in cost or timing before the extra work starts?', '/#find', FTC_HOME),
 ('windows', 'Windows & doors', 'Count openings. Then count exclusions.', 'Compare opening sizes, product specifications, removal, trim, finishing and disposal. Ask what happens if hidden deterioration is found. A per-window headline is only useful when the installation scope matches.', 'Is this the complete installed price for these exact openings?', '/#find', FTC_HOME),
 ('auto-repair', 'Auto repair & tires', 'A recommendation isn’t your authorization.', 'Ask for an estimate, the diagnostic charge and a clear process for approving additional work. For an expensive or complicated repair, the FTC suggests considering a second opinion. Ask about parts and written warranty terms.', 'Which work addresses my concern, and will you contact me before exceeding the estimate?', '/auto-mechanics/', FTC_AUTO),
 ('vehicle-wraps', 'Vehicle wraps & vinyl', 'A full wrap can still have exclusions.', 'Confirm the film, panels, preparation and finish. Ask about door jambs, existing film removal and surface condition. Sound Wraps’ published full-exterior starting price excludes door jambs; compare like coverage.', 'Which surfaces, preparation and materials are included in this quote?', '/vehicle-wraps/', WRAPS),
 ('real-estate', 'Real estate agents', 'Read the relationship before signing it.', 'Discuss the services, fee, duration, exclusivity and exit terms in the proposed agreement. NAR’s consumer guidance says buyer-agreement compensation and other terms are negotiable. Ask who may owe the fee and under what conditions.', 'What services am I buying, what could I owe, and how can this agreement end?', '/real-estate-agents/', NAR),
]


def add(out, origin, pages):
    e = html.escape
    def render(path, title, desc, body):
        write_editorial_page(out, origin, pages, path, title, desc, '<div class="wrap buying-page">'+body+'</div>')
    def price(title, value, scope, source, label):
        return '<article class="price-card"><p class="eyebrow">'+e(title)+'</p><h3>'+e(value)+'</h3><p>'+e(scope)+'</p><a href="'+source+'">'+e(label)+' ↗</a><small>Published reference · checked November 6, 2026</small></article>'

    intro='<div class="buying-intro"><div class="eyebrow">THE LOCAL PRICE NOTEBOOK</div><h1>Good help.<br><em>Clearer numbers.</em></h1><p class="buying-lede">What should it cost? Start with a real published number, then make sure you’re comparing the same work.</p><p>These are business-published price references, not a survey of typical local prices or a ceiling on what a project should cost. Starting prices describe a limited scope. Confirm current pricing, eligibility, taxes, exclusions and the complete written quote with the business before booking.</p><p><a href="/before-you-say-yes/">Spot the pressure. Ask the better question →</a></p></div>'
    jumps='<nav class="buying-jumps" aria-label="Price guide sections"><a href="#hvac">Heating & cooling</a><a href="#vehicle-wraps">Vehicle wraps</a><a href="#directory-prices">Every other category</a><a href="#method">Our method</a></nav>'
    hvac='<section id="hvac" class="buying-section"><div class="eyebrow">MIDDLETOWN HVAC · PUBLISHED ENTRY PRICES & PLANS</div><h2>Comfort, with a place to start.</h2><div class="price-grid">'
    hvac+=price('One-time maintenance', '$129', 'One visit for one eligible gas, propane or electric system; no annual commitment. Not the oil tune-up price. Repairs and other work require their own scope.', MAINTENANCE, 'Middletown’s published maintenance terms')
    hvac+=price('Oil tune-up', '$250', 'Published oil tune-up reference. Confirm the equipment, included work and any additional materials directly; the $129 eligible-system visit does not apply to oil.', MAINTENANCE, 'Read the oil-service terms')
    hvac+=price('Ductless installation', 'From $6,300', 'Middletown’s installed starting reference for a standard wall-mounted configuration. A planning figure, not a binding quote: equipment, electrical work, routes, drainage and site conditions affect the final scope.', DUCTLESS, 'Explore the published ductless estimator')
    hvac+=price('Annual maintenance plans', '$325 / $600', 'Published annual prices for two visits / four visits respectively, for one HVAC system. Confirm equipment eligibility, included work, renewal terms and additional-system pricing.', MAINTENANCE, 'Compare the published plan terms')
    hvac+='</div><p><a class="btn primary" href="/businesses/middletown-hvac/">Discuss your home with Middletown HVAC →</a> <a href="/services/ductless-mini-splits/">Explore room-by-room ductless comfort →</a></p></section>'
    wraps='<section id="vehicle-wraps" class="buying-section"><div class="eyebrow">SOUND WRAPS · WEST CHESTER</div><h2>A new look. A defined canvas.</h2><div class="price-grid">'
    wraps+=price('Full exterior wrap', 'Starting at $3,500', 'Sound Wraps publishes this starting price excluding door jambs. Material, vehicle, finish, coverage and complexity affect the quote.', WRAPS, 'Sound Wraps’ published services')
    wraps+=price('Hood, trunk or roof', '$350–$500', 'Published reference for a partial-panel project, not the price for all three panels together. Confirm the selected panel, vehicle, film and preparation.', WRAPS, 'Check partial-wrap scope')
    wraps+=price('Decals', '$75–$500', 'Sound Wraps’ published size-dependent decal range. Confirm design, coverage, preparation and installation details in the quote.', WRAPS, 'Check decal pricing')
    wraps+='</div><p><a class="btn primary" href="/businesses/sound-wraps-west-chester/">Meet Sound Wraps →</a></p></section>'
    other='<section id="directory-prices" class="buying-section"><div class="eyebrow">THE REST OF YOUR LOCAL SHORTLIST</div><h2>Price the actual project.</h2><p>We have not verified a fixed published rate for the categories below. Each needs a scope-specific written quote; we won’t fill the gap with an invented bargain. Use these questions to get a number you can actually compare.</p><div class="quote-grid">'
    for slug, label, headline, copy, question, destination, source in INDUSTRIES:
        if slug in ('hvac','vehicle-wraps'): continue
        other+='<article><span class="price-type">WRITTEN QUOTE NEEDED</span><h3>'+e(label)+'</h3><p>'+e(question)+'</p><a href="'+destination+'">Find the relevant local contact →</a><p><a href="/before-you-say-yes/#'+slug+'">Before you say yes →</a></p></article>'
    other+='</div></section>'
    method='<section id="method" class="buying-section buying-note"><h2>Our method: a source beside the number.</h2><p>Checked November 6, 2026. Numeric references above come from the linked business’s own published service pages or estimator. They are not independently audited transactions, competing bids, guaranteed availability or promises of the lowest price. Recheck the source and get a current written quote.</p><p>Wazoozie is connected with Middletown HVAC, and these pages can generate referrals to listed businesses. That relationship does not turn a starting price into a market average. Owner-recommended listings describe their evidence separately.</p><p><a href="/compare/">Compare two written estimates →</a> · <a href="/project-budget/">Build your project budget →</a> · <a href="/our-standards/">Read our directory standards →</a></p></section>'
    render('/pricing-guide/', 'Local Service Pricing Guide | HVAC, Vehicle Wraps & More', 'Sourced local HVAC maintenance, ductless and vehicle-wrap prices, with scope questions for plumbing, electrical, painting, repairs, auto and real estate.', intro+jumps+hvac+wraps+other+method)

    body='<div class="buying-intro"><div class="eyebrow">THE WAZOOZIE BUYER’S EDGE</div><h1>Less pressure.<br><em>Better questions.</em></h1><p class="buying-lede">The sales pitch can be polished. Your next question can be sharper.</p><p>A little homework for every corner of local life: the house, the car and the next move. These are questions to ask, not accusations about any particular business.</p><a class="btn primary" href="/pricing-guide/">Start with the sourced price guide →</a></div>'
    theater = '<section id="fine-print-theater" class="fine-print-theater"><div class="eyebrow">WELCOME TO FINE PRINT THEATER</div><h2>Big headline.<br><em>Now for the small print.</em></h2><p>Familiar sales-pitch scenarios, with the questions that bring the full cost into view. These are illustrative examples, not verified offers or findings against a named company. A low fee, large business or promotion is not, by itself, evidence of misconduct.</p><div class="theater-grid">'
    acts = [
      ('01', 'The $49 service-call spectacular', 'The headline gets your attention. What does it actually buy?', 'A dispatch fee, diagnostic assessment and repair are different things. An advertised $49 call may cover only a particular visit or promotion. Ask whether diagnostic time, after-hours charges or other mandatory fees are separate, and what you owe if you decline repairs.', 'Before I book: what is the total charge to assess this problem, what is excluded, and what do I owe if I approve no further work?', FTC_AUTO),
      ('02', 'The discount that turns into a pumpkin', '“Only if you sign before I leave.”', 'Ask for the complete proposal and the promotion’s written end date and eligibility. A deadline does not establish that the work is needed or the price is competitive. If the situation is safe to leave, give yourself time to compare.', 'Please leave the written scope and offer terms so I can review the decision.', FTC_HOME),
      ('03', 'The monthly-payment magic trick', 'A little number can hide a long commitment.', 'Ask for the cash price, amount financed, APR, term, fees and total of payments. Check promotional conditions and what happens when the promotion ends. The FTC’s car-financing guidance explains why the monthly payment alone is an incomplete comparison; apply that same question to any financed project.', 'What is the complete cash price, and what is the total I would pay under this financing offer?', 'https://consumer.ftc.gov/articles/financing-or-leasing-car'),
      ('04', 'The mystery add-on encore', 'The estimate has left the stage. A new charge has entered.', 'Ask which items are necessary for the agreed work and which are optional. Get the cost and your approval documented before an addition proceeds. An extra charge needs an explanation, not just a new line on the final invoice.', 'What is this item, why is it needed, and did I authorize it at this price?', FTC_AUTO),
      ('05', 'The “while we’re here” upgrade parade', 'A long list does not tell you what matters first.', 'Separate the original concern, documented safety findings, maintenance and optional improvements. Ask what each recommendation addresses and what happens if you defer it. Deal with genuine hazards promptly; have the qualified professional explain the immediate precautions.', 'Which item fixes my original problem, which is urgent, and which is optional?', FTC_HOME),
      ('06', 'The bargain with a backstage door', 'The low number has an exclusions list.', 'Compare the same work: materials, preparation, removal, permits, finishing and follow-up. Sound Wraps, for example, clearly excludes door jambs from its published full-exterior starting price. A stated exclusion helps you compare; an unexplained one leaves you guessing.', 'Can you mark every exclusion and allowance on the written proposal before I decide?', WRAPS),
    ]
    for number, title, setup, explanation, question, source in acts:
        theater += '<details class="theater-act"><summary><span>ACT '+number+'</span><h3>'+e(title)+'</h3><p>'+e(setup)+'</p><b>Pull back the curtain +</b></summary><div class="theater-reveal"><p>'+e(explanation)+'</p><div class="ask-box"><span>YOUR LINE</span><p>“'+e(question)+'”</p></div><a href="'+source+'">Consumer guidance & context ↗</a></div></details>'
    theater += '</div><p class="theater-footnote">No coupon can answer these questions for you. A good contractor or affiliate should be able to explain the offer, scope and approval process.</p><a class="btn primary" href="/pricing-guide/">Compare sourced prices and scopes →</a></section>'
    body += theater
    body+='<nav class="buying-jumps" aria-label="Industry questions">'+''.join('<a href="#'+s+'">'+e(label)+'</a>' for s,label,*_ in INDUSTRIES)+'</nav><div class="buyer-grid">'
    for slug,label,headline,copy,question,destination,source in INDUSTRIES:
        body+='<article id="'+slug+'" class="buyer-card"><div class="eyebrow">'+e(label)+'</div><h2>'+e(headline)+'</h2><p>'+e(copy)+'</p><div class="ask-box"><span>TRY ASKING</span><p>“'+e(question)+'”</p></div><div class="buyer-links"><a href="'+destination+'">Explore local help →</a><a href="'+source+'">Source & context ↗</a></div></article>'
    body+='</div><section class="buying-section buying-note"><div class="eyebrow">THE NAME ON THE TRUCK IS THE START</div><h2>Who stands behind the work?</h2><p>Ask which legal business you are hiring, who will perform the work, who handles a complaint and who is responsible for written warranty terms. If ownership has changed, ask whether your existing agreement and service arrangements have changed too.</p><p>A local-looking brand may be independently owned, part of a larger group or owned by an investment firm. Ownership alone does not establish service quality. Clear findings, written scope, authorized changes and accountable follow-up give you something concrete to judge.</p><h3>Small businesses. Reputations worth protecting.</h3><p>Wazoozie is built to give small businesses, contractors and local affiliates with strong reputations a place to be discovered. Start with a recommendation, read the listing’s evidence and speak directly with the people behind the work. Put a locally recommended business on your shortlist. Give it the same scope, ask the same questions and compare complete written proposals. The strongest introduction ends with a business earning your confidence.</p><p>For immediate danger, address safety first. These shopping questions do not establish whether equipment or a property is safe.</p><p>Editorial synthesis based on <a href="'+FTC_HOME+'">FTC home-improvement guidance</a>, <a href="'+FTC_AUTO+'">FTC auto-repair guidance</a>, <a href="'+NAR+'">NAR’s buyer-agreement guide</a> and <a href="'+WRAPS+'">Sound Wraps’ published coverage and pricing</a>. Checked November 6, 2026. Wazoozie is connected with Middletown HVAC; recommendations are not guarantees.</p></section>'
    render('/before-you-say-yes/', 'Before You Say Yes | Questions for Every Local Service', 'Spot sales pressure, clarify exclusions and ask better questions across HVAC, plumbing, electrical, painting, remodeling, auto repair, wraps and real estate.', body)

    teaser='<section class="wrap buying-home" aria-labelledby="buying-home-title"><div><div class="eyebrow">A LITTLE SAVVY LOOKS GOOD ON YOU.</div><h2 id="buying-home-title">A better price starts<br>with a better question.</h2><p>Real published starting points. Fine Print Theater. A sharper question for every industry.</p></div><div><a class="btn primary" href="/pricing-guide/">Open the local price notebook →</a><a class="buying-text-link" href="/before-you-say-yes/#fine-print-theater">Visit Fine Print Theater →</a></div></section>'
    home=out/'index.html';s=home.read_text().replace('<section class="wrap journal-home"',teaser+'<section class="wrap journal-home"',1);home.write_text(s)
    for target in out.rglob('*.html'):
        s=target.read_text().replace('<strong>The useful details</strong>','<strong>The useful details</strong><a href="/pricing-guide/">Sourced pricing guide</a><a href="/before-you-say-yes/">Before you say yes</a>',1)
        s=s.replace('</head>','<link rel="stylesheet" href="/assets/buying.css"></head>',1)
        target.write_text(s)
    shutil.copy(out.parent/'assets/buying.css',out/'assets/buying.css')
